  CV = `Sin categoría`,
  wV = `Tal vez fue su jugabilidad inmersiva, o su apasionante historia... sus personajes bien diseñados, su impecable diseño o el multijugador adictivo. Cualquiera que sea la razón, el ganador del Premio "Juego del año" 2020 es un clásico instantáneo.`,
  TV = `El Juego de RV del año no se presenta simplemente como una realidad normal. Este juego perfecciona la realidad, aprovechando el medio de la RV y superando los límites del entorno virtual.`,
  EV = `Este juego ha estado disponible durante un tiempo. Atrás quedaron los días en que los creadores de este juego anunciaron el debut de su bebé creativo, pero como son buenos padres, continuaron desarrollando y apoyando su creación. Este juego, actualmente, todavía recibe nuevo contenido incluso después de todos estos años.`,
  DV = `Hay algunos juegos que no son igual de entretenidos cuando los juegas solo. Quizás necesites tener un amigo que te vigile la espalda. Tal vez necesites tener un amigo que puedas apuñalar por la espalda. De cualquier manera, la diversión espera a quienes se reúnen con sus amigos para jugar estos juegos.`,
  OV = `El estilo visual no aspira a la fidelidad gráfica del mundo real (aunque noble objetivo en sí mismo)… describe un aspecto y un comportamiento distintivos que impregnan un juego al completo.`,
  kV = `Los creadores de este juego están a la vanguardia de la experimentación, ofreciendo nuevas perspectivas y sorpresas increíbles. Este juego deleitó, inspiró y entretuvo con sus elementos originales.`,
  AV = `Este es el juego que premia la perseverancia. No es para todos. Es el juego más difícil que jamás hemos amado.`,
  jV = `Este héroe anónimo merece ser reconocido por su excepcional banda sonora. ¡Es definitivamente la mejor! `,
  MV = `Algunos días, solo un juego con mucha narración dará en el clavo, y este tiene un gran éxito. Es tan apasionante como cualquier telenovela, y tan bien afinado como un guión de TV de prestigio. Bravísimo: ¡por hacernos sentir así!`,
