  TH = `Los diseñadores de este juego están a la vanguardia de la experimentación creativa, ofreciendo nuevas perspectivas y sorpresas alucinantes. Este juego encantó, inspiró y entretuvo gracias a sus elementos originales.`,
  EH = `Este es el juego que premia la perseverancia. No es para todos. Es el juego más difícil que jamás hemos amado.`,
  DH = `Este héroe anónimo merece ser reconocido por su excepcional banda sonora. ¡Es definitivamente la mejor! `,
  OH = `Algunos días, solo un juego con mucha narración dará en el clavo, y este pega fuerte. Es tan apasionante como cualquier telenovela, y tan bien afinado como un guion de TV de prestigio. ¡Bravísimo por hacernos sentir así!`,
  kH = `Este juego es el antídoto perfecto contra un día ajetreado: es tranquilo, relajante y hace que tus preocupaciones se desvanezcan. Es tu momento zen.`,
