  eU = `Visitar el Mercado ahora`,
  tU = `Recibiste %1$s fichas`,
  nU = `Tu saldo`,
  rU = `%1$s fichas`,
  iU = `No se puede abrir el sobre`,
  aU = `LA GRAN CARRERA DEL EMPERADOR`,
  oU = `El origen del horóscopo chino`,
  sU = `Parte I de IV`,
  cU = `Parte II de IV`,
  lU = `Parte III de IV`,
  uU = `Parte IV de IV`,
  dU = `El Emperador de Jade invocó a todas las criaturas de su reino a competir en una carrera hacia la corte celestial declarando que los primeros doce en llegar serían honrados con un lugar en su nuevo calendario.

La inteligente rata fue la primera en llegar al dominio celestial. Como no le gustaba nadar, se subió al lomo del confiable buey, saltando entusiasmada al jardín celestial del emperador justo antes de que el buey llegara a la orilla.

El constante Buey cruzó el río con facilidad. Sin preocuparse por los resultados de la carrera, el buey se sentía satisfecho con su papel en el éxito de la rata.`,
  fU = `El autosuficiente tigre viajó con demasiado cuidado para superar al buey, pensando que quedar tercero era mejor que nada.

El veloz conejo saltó sobre un tronco flotando sin rumbo, pero la suerte le sonrió ya que un viento útil lo impulsó con seguridad en su rumbo.

La perspectiva del dragón volador reveló a una aldea en necesidad, así que se detuvo para ayudar, incluso hasta para regalarle una ráfaga de viento al conejo en el río. El honor era mucho más importante que la victoria y el dragón encontró que la quinta posición le iba bien.`,
  pU = `La sigilosa serpiente no estaba muy interesada en esforzarse demasiado, así que se enrolló alrededor de una de las pezuñas delanteras del caballo sin que nadie lo notara.

Mientras el caballo galopaba hacia la meta, la serpiente se desenrolló, asustando al corcel lo suficiente como para arrastrarse hacia la sexta posición con el temeroso caballo trotando inmediatamente detrás de ella.`,
  mU = `La oveja, el mono y el gallo trabajaron juntos, pero dejaron que la oveja reclamara la octava posición como recompensa por la ayuda durante el viaje. El mono obtuvo la novena posición y el gallo la décima, orgulloso de que el orden fuera justo.

El juguetón perro estaba más interesado en jugar en el agua que en ganar, por lo que terminó siendo el undécimo: un buen negocio considerando toda la diversión.

En la duodécima posición, llegó el cerdo, que se había detenido para comer y dormir; siendo lo suficientemente sabio como para saber que cada animal tendría su momento con el emperador.`,
  hU = `Los cambios en el perfil tendrán efecto tras su revisión`,
